  if(e.kind==='chest'){if(this.state.opened.includes(e.id)){this.toast('O baú já está vazio.');return;}this.state.opened.push(e.id);if(e.id.startsWith('semente-')){this.save();this.toast(`Semente ${e.id==='semente-porto'?'do cais':'da Galeria'} guardada na bolsa. Leve as duas amostras a Ava.`);return;}this.state.potions+=2;this.state.ethers++;if(['glifo-bau','jardim-bau'].includes(e.id))this.state.credits+=60;this.save();this.notify('Encontrou 2 Poções e 1 Elixir de Éter.'+(['glifo-bau','jardim-bau'].includes(e.id)?' +60 créditos.':''),'bag','potion');return;}
