 drawCosmetics(count:1|5|10,random?:()=>number){const p=this.state.progress;if(this.state.mode!=='world'||this.state.gachaBusy||![1,5,10].includes(count)||!p.masterMode&&p.tokens<count)return false;if(!p.masterMode)p.tokens-=count;const results:{id:string;duplicate:boolean}[]=[];for(let i=0;i<count;i++){const item=chooseCosmetic(p.pity,random),duplicate=p.cosmetics.includes(item.id);p.rolls++;p.pity=item.rank>=4?0:p.pity+1;p.lastDraw=item.id;p.lastDuplicate=duplicate;if(duplicate)p.dust+=item.rank;else{p.cosmetics.push(item.id);p.unseenCosmetics.push(item.id);}results.push({id:item.id,duplicate});}this.state.gachaResults=results;this.state.gachaBusy=true;this.soundEffect('gacha');this.save();this.emit();setTimeout(()=>{if(this.state.progress!==p||this.state.gachaResults!==results)return;this.state.gachaBusy=false;this.notify(`${count} ${count>1?'invocações':'invocação'}: ${results.filter(v=>!v.duplicate).length} novas auras.`, 'gacha',results.find(v=>!v.duplicate)?.id);},1800);return true;}
