 swapLeader(){if(this.state.mode!=='world'||this.paused||this.state.heroes.length<2)return false;this.state.progress.party.reverse();this.state.heroes.reverse();this.clearMovement();this.save();this.toast(`${this.state.heroes[0].name} lidera. Q e R acompanham suas técnicas.`);return true;}
