 challengeRecruit(id:HeroId){const p=this.state.progress,base=heroBases().find(h=>h.id===id);if(this.state.mode!=='world'||['beatriz','orfeu','ava','carmilla'].includes(id)||!base||p.recruited.includes(id))return false;this.beginBattle({id:`duel-${id}`,eventId:`recruit-${id}`,label:`Duelo de recrutamento · ${base.name}`,kind:'mob',x:this.state.position.x,y:this.state.position.y,asset:id,family:'sombra',hp:Math.round(base.maxHp*2.2),damage:Math.max(14,base.atk),xp:80,credits:90});return true;}
 talkWithCompanion(){const id=this.state.heroes[0].id,companion=COMPANIONS[id];if(this.state.mode!=='world'||!companion)return false;this.say([{speaker:companion.name,right:id,text:companion.line,present:true}]);return true;}
 autoEquip(hero:HeroId){const p=this.state.progress;if(this.state.mode!=='world')return false;const unavailable=new Set(PLAYABLE_HERO_IDS.filter(id=>id!==hero).flatMap(id=>Object.values(p.equipment[id])));const score=(item:NonNullable<ReturnType<typeof gearById>>)=>item.hp*.25+item.mp*.3+item.atk*(hero==='ophelia'?1:2)+(item.spell||0)*(hero==='ophelia'?2:1);for(const slot of SLOTS){const candidates=p.owned.filter(id=>{const i=gearById(id);return i&&i.slot===slot&&!unavailable.has(id)&&(!i.hero||i.hero===hero)&&(i.minLevel||1)<=level(p);}).sort((a,b)=>score(gearById(b)!)-score(gearById(a)!));if(candidates[0])p.equipment[hero][slot]=candidates[0];}this.recalculateGear();this.toast('Equipamentos selecionados por atributos; peças de outros heróis são preservadas.');return true;}
 autoEquipAura(hero:HeroId){const p=this.state.progress;if(this.state.mode!=='world')return false;const options=p.cosmetics.filter(id=>!PLAYABLE_HERO_IDS.some(h=>h!==hero&&p.cosmeticEquipment[h]===id)).sort((a,b)=>cosmeticById(b)!.rank-cosmeticById(a)!.rank);if(!options[0])return false;return this.equipCosmetic(hero,options[0]);}
 finishProfessorBond(id:'orfeu'|'ava'){const p=this.state.progress;if(!p.summoned.includes(id)||p.bonded.includes(id))return; p.bonded.push(id);if(!p.recruited.includes(id)){p.recruited.push(id);const base=heroBases().find(h=>h.id===id)!;p.reserveVitals[id]={hp:base.maxHp,mp:base.maxMp};}this.notify(`${id==='orfeu'?'Orfeu':'Ava'}: vínculo concluído; disponível no Grupo.`, 'party', id);}
